// Title: May The Dots Be With You
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

// ShaderToy-Compatible GLSL Code
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalize coordinates to range -1.0 to 1.0
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Background color
    vec3 bgColor = vec3(0.05, 0.05, 0.1);
    vec3 color = bgColor;

    // Grid and animation parameters
    float gridSize = 5.0;  // Number of grid divisions
    float time = iTime * 0.7;

    // Loop over a 3D grid for more depth
    for (float x = -gridSize; x <= gridSize; x++) {
        for (float y = -gridSize; y <= gridSize; y++) {
            for (float z = -gridSize * 0.5; z <= gridSize * 0.5; z++) {
                // Node position with simple oscillation
                vec3 nodePos = vec3(x, y, z) + 0.2 * sin(vec3(x, y, z) * 1.5 + time);

                // Project 3D to 2D space
                vec2 proj = nodePos.xy / (1.0 + nodePos.z * 0.2);

                // Calculate distance to the node
                float dist = length(uv - proj);

                // Add nodes with vibrant colors
                float nodeSize = 0.02;
                vec3 nodeColor = 0.5 + 0.5 * cos(vec3(1.0, 2.0, 3.0) + nodePos.x * 0.5 + time);
                color += smoothstep(nodeSize * 1.5, nodeSize, dist) * nodeColor;

                // Draw connecting lines for nearby nodes
                if (dist < 0.15) {
                    vec2 dir = normalize(uv - proj);
                    float lineThickness = 0.005;
                    float lineDist = abs(dot(uv - proj, vec2(-dir.y, dir.x)));
                    color += smoothstep(lineThickness * 2.0, lineThickness, lineDist) * vec3(1.0);
                }
            }
        }
    }

    // Output the color
    fragColor = vec4(color, 1.0);
}
